import React, { useState } from 'react';
import AgentModal from './AgentModal';

function AgentGrid({
  agents,
  purchasedMap,
  accessStatus,
  authToken,
  apiBase,
  onLoadAgents
}) {
  const [selectedAgent, setSelectedAgent] = useState(null);
  const [showModal, setShowModal] = useState(false);

  const formatCapability = (capability) =>
    capability
      .split('-')
      .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
      .join(' ');

  const handleAgentClick = (agent) => {
    setSelectedAgent(agent);
    setShowModal(true);
  };

  const handleCloseModal = () => {
    setShowModal(false);
    setTimeout(() => setSelectedAgent(null), 300);
  };

  return (
    <>
      <div className="agent-grid">
        {agents.map((agent) => {
          const status = accessStatus[agent.id] || {};
          const isPurchased = status.is_purchased;
          const demoUsesLeft = status.demo_uses_left || 0;
          const purchased = purchasedMap && purchasedMap[agent.id];

          return (
            <div
              key={agent.id}
              className="agent-card"
              onClick={() => handleAgentClick(agent)}
            >
              <div className="agent-card-top">
                <div className="agent-icon">AI</div>
                <span className="agent-id-pill">{agent.id}</span>
              </div>
              <h3 className="agent-name">{agent.name}</h3>
              <p className="agent-description">{agent.description}</p>
              <div className="agent-purpose">
                <strong>Purpose:</strong> {agent.purpose}
              </div>
              <div className="capabilities">
                {agent.capabilities.map((cap, idx) => (
                  <span key={idx} className="capability-badge">
                    {formatCapability(cap)}
                  </span>
                ))}
              </div>
              <div className="agent-status">
                {agent.status}
              </div>
              <div className="demo-badge">
                {isPurchased ? (
                  <span style={{ color: '#86efac' }}>✓ Owned</span>
                ) : (
                  <span>Demo: {demoUsesLeft} try{demoUsesLeft !== 1 ? 'ies' : ''} left</span>
                )}
              </div>
              <div className="agent-actions-row">
                <span className="agent-hint">
                  ➤ Click for details
                </span>
                {isPurchased ? (
                  <button 
                    className="btn btn-success" 
                    style={{ marginLeft: 'auto' }}
                    onClick={(e) => {
                      e.stopPropagation();
                      handleAgentClick(agent);
                    }}
                    title="Click to view access details and credentials"
                  >
                    Access
                  </button>
                ) : (
                  <button 
                    className="btn btn-primary" 
                    style={{ marginLeft: 'auto' }}
                    onClick={(e) => {
                      e.stopPropagation();
                      handleAgentClick(agent);
                    }}
                  >
                    Buy
                  </button>
                )}
              </div>
            </div>
          );
        })}
      </div>

      {showModal && selectedAgent && (
        <AgentModal
          agent={selectedAgent}
          purchased={purchasedMap && purchasedMap[selectedAgent.id]}
          accessStatus={accessStatus[selectedAgent.id] || {}}
          authToken={authToken}
          apiBase={apiBase}
          onClose={handleCloseModal}
          onLoadAgents={onLoadAgents}
        />
      )}
    </>
  );
}

export default AgentGrid;
